  FIGURES["ld-cours-uniforme"] = () => ldBatons([1, 2, 3, 4], [0.25, 0.25, 0.25, 0.25], { ystep: 0.05, yetiq: 0.25, hi: [3, 4], aria: "Loi uniforme sur 1, 2, 3, 4 : quatre bâtons de hauteur 0,25 ; les bâtons de 3 et 4, en couleur, forment l'événement X ⩾ 3" });
  FIGURES["ld-cours-arbre"] = () => vaArbre(2, 0.7);
