      let dx, dy; do { dx = randNZ(-3, 3); dy = randNZ(-3, 3); } while (Math.abs(dx) === Math.abs(dy));
      const cand = shuffle([[dx, dy], [dy, dx], [-dx, dy], [dx, -dy]]), noms = ["a", "b", "c", "d"], centres = [[-3, 2.5], [3, 2.5], [-3, -2.5], [3, -2.5]];
      const fl = cand.map(([u, v], k) => { const ox = Math.round(centres[k][0] - u / 2), oy = Math.round(centres[k][1] - v / 2); return { x1: ox, y1: oy, x2: ox + u, y2: oy + v, label: noms[k], c: k % 2 }; });
