    const choix = ["isocèle en $A$, mais pas rectangle", "rectangle en $A$, mais pas isocèle", "isocèle et rectangle en $A$", "ni isocèle en $A$, ni rectangle en $A$"];
    const iso = AB2 === AC2, rect = AB2 + AC2 === BC2, rep = iso && rect ? 2 : iso ? 0 : rect ? 1 : 3;
