    const P = ctx ? pcValeurs(ctx) : pcBranches(), lab = P.map(pcV), Xt = pcTex(noms[0]), Yt = pcTex(noms[2]);
    const intro = ctx ? `${ctx.intro} On note ${ctx.leg}. ` : "";
