  GEN["ec-python"] = function () {
    // Simulation : vers quelle valeur exacte la fréquence se rapproche-t-elle (loi des grands nombres) ?
    // RJ : tirages rangés dans des variables, pour des lignes courtes (écran de 360 px)
    const t = pick([0, 0, 1, 1, 2, 2, 2, 3, 3, 4, 4, 5, 6]), RI = "from random import randint\n\ndef experience():\n    return ", RJ = "from random import randint\n\ndef experience():\n";
    const tt = (s) => `$\\texttt{${s}}$`;
    let code, num, den, expl, err = [];
    if (t === 0) {
      // un entier précis avec randint(1, N)
      const N = pick([4, 6, 6, 8, 10, 12, 20]), v = rand(1, N);
      code = RI + `randint(1, ${N}) == ${v}`; num = 1; den = N;
      expl = `${tt(`randint(1, ${N})`)} donne un entier au hasard de $1$ à $${N}$ (les deux bornes comprises), avec la même probabilité : obtenir $${v}$ a la probabilité $\\dfrac{1}{${N}}$.`;
      err = [{ valeur: 1 / (N - 1), message: `$\\texttt{randint(1, ${N})}$ peut donner $${N}$ valeurs : de $1$ à $${N}$, les deux bornes comprises.` }, { valeur: 1 / 2, message: `« Obtenir $${v}$ ou pas » : ces deux cas ne sont pas équiprobables.` }];
    } else if (t === 1) {
      // parité ou multiples avec %
      const [N, m, r] = pick([[6, 2, 0], [6, 2, 1], [6, 3, 0], [8, 2, 0], [8, 3, 0], [10, 3, 0], [10, 4, 0], [12, 5, 0], [12, 3, 0], [20, 3, 0], [20, 6, 0], [10, 2, 1], [12, 4, 0], [20, 7, 0], [9, 2, 1], [15, 4, 0]]);
      const favo = []; for (let x = 1; x <= N; x++) if (x % m === r) favo.push(x);
      code = RI + `randint(1, ${N}) % ${m} == ${r}`; num = favo.length; den = N;
      const quoi = m === 2 ? (r === 0 ? "pair" : "impair") : `un multiple de $${m}$`;
      expl = `${tt(`n \\% ${m}`)} est le reste de la division de $n$ par $${m}$ : le test est vrai quand le nombre tiré est ${quoi}, soit pour $${favo.join("$, $")}$ : $${favo.length}$ issues sur $${N}$.`;
      err = [{ valeur: 1 / m, message: `Il n'y a pas exactement une issue sur $${m}$ ici : écris la liste des entiers de $1$ à $${N}$ qui conviennent.` }, { valeur: (N - favo.length) / N, message: "Ça, c'est la probabilité que le test soit faux." }, { valeur: favo.length / (N - 1), message: `$\\texttt{randint(1, ${N})}$ donne $${N}$ valeurs possibles, bornes comprises.` }];
    } else if (t === 2) {
      // inférieur ou égal, supérieur ou égal, strict
      const N = pick([6, 8, 10, 12, 20]), k = rand(2, N - 1), op = pick(["<=", ">=", ">", "<"]);
      num = { "<=": k, ">=": N - k + 1, ">": N - k, "<": k - 1 }[op]; den = N;
      const mots = { "<=": "inférieur ou égal à", ">=": "supérieur ou égal à", ">": "strictement supérieur à", "<": "strictement inférieur à" }[op];
      const L = { "<=": [1, k], ">=": [k, N], ">": [k + 1, N], "<": [1, k - 1] }[op];
      code = RI + `randint(1, ${N}) ${op} ${k}`;
      expl = `Le test est vrai quand l'entier tiré (de $1$ à $${N}$) est ${mots} $${k}$ : ${L[0] === L[1] ? `l'entier $${L[0]}$` : `les entiers de $${L[0]}$ à $${L[1]}$`}, soit $${num}$ issues sur $${N}$.`;
      err = [{ valeur: (op === "<=" || op === ">=" ? num - 1 : num + 1) / N, message: op === "<=" || op === ">=" ? `Le signe ${tt(op)} veut dire « ${mots} » : $${k}$ compte aussi.` : `Le signe ${tt(op)} est strict : $${k}$ ne compte pas.` }, { valeur: (N - num) / N, message: "Ça, c'est la probabilité que le test soit faux." }];
    } else if (t === 3) {
      // random() < p ou random() > p
      const p = pick([0.1, 0.15, 0.2, 0.25, 0.3, 0.35, 0.4, 0.45, 0.6, 0.65, 0.7, 0.75, 0.8, 0.85, 0.9]), inf = Math.random() < 0.6;
      code = `from random import random\n\ndef experience():\n    return random() ${inf ? "<" : ">"} ${p}`;
      num = inf ? p : +(1 - p).toFixed(2); den = 1;
      expl = `${tt("random()")} donne un nombre au hasard dans $[0\\,;1[$ : il est ${inf ? "inférieur" : "supérieur"} à $${fr(p)}$ avec la probabilité $${inf ? fr(p) : `1 - ${fr(p)} = ${fr(num)}`}$.`;
      err = [{ valeur: inf ? +(1 - p).toFixed(2) : p, message: inf ? `Le test ${tt(`random() < ${p}`)} est vrai pour les nombres **inférieurs** à $${fr(p)}$ : une proportion $${fr(p)}$ de l'intervalle $[0\\,;1[$.` : `Le test est ${tt(`random() > ${p}`)} : on veut les nombres **supérieurs** à $${fr(p)}$.` }, { valeur: 0.5, message: "Le nombre tiré n'a pas une chance sur deux d'être de chaque côté : regarde où se trouve la limite dans $[0\\,;1[$." }];
    } else if (t === 4) {
      // somme de deux dés à N faces
      const N = pick([4, 6, 6, 8]), s = rand(2, 2 * N), c = N - Math.abs(s - (N + 1));
      const couples = []; for (let a = 1; a <= N; a++) { const b = s - a; if (b >= 1 && b <= N) couples.push([a, b]); }
      const nonOrd = couples.filter(([a, b]) => a <= b).length, paires = (N * (N + 1)) / 2;
      code = RJ + `    d1 = randint(1, ${N})\n    d2 = randint(1, ${N})\n    return d1 + d2 == ${s}`; num = c; den = N * N;
      expl = `Avec deux dés à $${N}$ faces, il y a $${N} \\times ${N} = ${N * N}$ couples équiprobables. Somme $${s}$ : $${couples.map(([a, b]) => `(${a}\\,;${b})`).join("$, $")}$, soit $${c}$ couple${c > 1 ? "s" : ""}.`;
      err = [{ valeur: 1 / (2 * N - 1), message: `Les $${2 * N - 1}$ sommes possibles (de $2$ à $${2 * N}$) ne sont **pas** équiprobables : compte les couples dans un tableau $${N} \\times ${N}$.` }, { valeur: nonOrd / paires, message: `$(1\\,;2)$ et $(2\\,;1)$ sont deux issues différentes : il y a $${N * N}$ couples équiprobables, pas $${paires}$ paires.` }];
    } else if (t === 5) {
      // un double (ou pas de double)
      const N = pick([4, 6, 6, 8, 10, 12]), pas = Math.random() < 0.35;
      code = RJ + `    d1 = randint(1, ${N})\n    d2 = randint(1, ${N})\n    return d1 ${pas ? "!=" : "=="} d2`; num = pas ? N - 1 : 1; den = N;
      expl = `Il y a $${N} \\times ${N} = ${N * N}$ couples équiprobables, dont $${N}$ doubles. ${pas ? `Le test ${tt("!=")} (« différent de ») est vrai quand les deux nombres sont différents : $${N * N} - ${N} = ${N * N - N}$ couples, soit $\\dfrac{${N * N - N}}{${N * N}}$.` : `Le test est vrai pour un double : $\\dfrac{${N}}{${N * N}}$.`}`;
      err = [{ valeur: pas ? 1 - 1 / (N * N) : 1 / (N * N), message: "Il n'y a pas un seul double : il y en a autant que de valeurs possibles." }, { valeur: pas ? 1 - 2 / (N + 1) : 2 / (N + 1), message: `On compte des couples ordonnés : il y a $${N * N}$ couples équiprobables.` }];
    } else {
      // pièces codées 0 / 1 : deux ou trois pièces
      const trois = Math.random() < 0.45, k = trois ? rand(0, 3) : rand(0, 2), tot = trois ? 8 : 4, nbF = trois ? [1, 3, 3, 1][k] : [1, 2, 1][k];
      code = RJ + "    p1 = randint(0, 1)\n    p2 = randint(0, 1)\n" + (trois ? "    p3 = randint(0, 1)\n    return p1 + p2 + p3" : "    return p1 + p2") + ` == ${k}`; num = nbF; den = tot;
      expl = `Chaque ${tt("randint(0, 1)")} donne $0$ ou $1$ comme une pièce. ${trois ? "Avec trois pièces, l'arbre a $8$ chemins équiprobables" : "Avec deux pièces, il y a $4$ couples équiprobables $(0\\,;0)$, $(0\\,;1)$, $(1\\,;0)$, $(1\\,;1)$"} ; la somme vaut $${k}$ pour $${nbF}$ d'entre eux.`;
      err = [{ valeur: 1 / (trois ? 4 : 3), message: `Les sommes $0$, $1$${trois ? ", $2$ et $3$" : " et $2$"} ne sont pas équiprobables : fais l'arbre.` }, { valeur: 1 / tot, message: `Plusieurs chemins de l'arbre donnent la somme $${k}$ : compte-les.` }];
    }
    const p = num / den;
    if (Math.abs(p * 1e4 - Math.round(p * 1e4)) > 1e-9) err.push({ valeur: Math.round(p * 100) / 100, message: "Donne la valeur exacte, sous forme de fraction." });
    const valTex = den === 1 ? fr(p) : `${frac(num, den)}${Math.abs(p * 1e4 - Math.round(p * 1e4)) < 1e-9 && den > 1 && !Number.isInteger(p) ? ` = ${nb(+p.toFixed(4))}` : ` \\approx ${nb(+p.toFixed(3))}`}`;
    return {
      enonce: "On considère le programme :\n\n```python\n" + code + "\n\ndef frequence(n):\n    c = 0\n    for i in range(n):\n        if experience():\n            c = c + 1\n    return c / n\n```\n\nPour $n$ très grand, vers quelle valeur $\\texttt{frequence(n)}$ se rapproche-t-elle ? Donne la valeur exacte (fraction ou décimal).",
      mode: "nombre", prefixe: "Valeur :", attendu: p,
      erreurs: err.filter((e, k) => Math.abs(e.valeur - p) > 1e-9 && err.findIndex((f) => Math.abs(f.valeur - e.valeur) < 1e-9) === k),
      aides: ["$\\texttt{frequence(n)}$ répète $n$ fois l'expérience et renvoie la fréquence des succès.", "D'après la loi des grands nombres, cette fréquence se rapproche de la probabilité de succès.", "Calcule la probabilité que $\\texttt{experience()}$ renvoie $\\texttt{True}$."],
      solution: `${expl}\n\nPour $n$ grand, $\\texttt{frequence(n)}$ se rapproche de la probabilité $${valTex}$.`
    };
  };


  /* ---------- Schémas des cours de Seconde (chapitres 4 à 17) ---------- */
  // Tableau de signes. xs : valeurs de la 1re ligne (textes, ±∞ compris) ;
  // lignes : [{ nom, cases }] avec cases = [signe, marque, signe, marque, …, signe] (marque : "0", "||" ou "")
  function tabsigne(xs, lignes) {
    const W = 320, g = 78, hR = 30, H = hR * (lignes.length + 1) + 2, n = xs.length;
    const X = (k) => g + 16 + (k * (W - g - 32)) / (n - 1);
    let s = `<svg class="graph tabvar" viewBox="0 0 ${W} ${H}" role="img" aria-label="Tableau de signes">`;
    s += `<g class="g-axis"><rect x="1" y="1" width="${W - 2}" height="${H - 2}" fill="none" stroke-width="1.2" style="stroke:var(--doux)"/><line x1="${g}" y1="1" x2="${g}" y2="${H - 1}"/>`;
    for (let r = 1; r <= lignes.length; r++) s += `<line x1="1" y1="${r * hR}" x2="${W - 1}" y2="${r * hR}"/>`;
    s += `</g><text class="g-label" x="${g / 2}" y="20" text-anchor="middle">x</text>`;
    xs.forEach((x, k) => { s += `<text class="g-label" x="${X(k)}" y="20" text-anchor="middle">${x}</text>`; });
    lignes.forEach((l, r) => {
      const y0 = (r + 1) * hR, yc = y0 + 20, der = r === lignes.length - 1;
      s += `<text class="g-label" x="${g / 2}" y="${yc}" text-anchor="middle" ${der ? 'style="fill:var(--lagon)"' : ""}>${l.nom}</text>`;
      l.cases.forEach((c, i) => {
        if (i % 2 === 0) { const xm = (X(i / 2) + X(i / 2 + 1)) / 2; s += `<text class="g-clabel" x="${xm}" y="${yc + 1}" text-anchor="middle" style="fill:${c === "+" ? "var(--lagon)" : c === "?" ? "var(--ylang)" : "var(--faux)"}">${c === "-" ? "−" : c}</text>`; }
        else {
          const xv = X((i + 1) / 2);
          if (c === "||") s += `<line x1="${xv - 2}" y1="${y0}" x2="${xv - 2}" y2="${y0 + hR}" style="stroke:var(--encre);stroke-width:1.2"/><line x1="${xv + 2}" y1="${y0}" x2="${xv + 2}" y2="${y0 + hR}" style="stroke:var(--encre);stroke-width:1.2"/>`;
          else { s += `<line x1="${xv}" y1="${y0}" x2="${xv}" y2="${y0 + hR}" style="stroke:var(--trait);stroke-width:1;stroke-dasharray:3 3"/>`; if (c) s += `<text class="g-label" x="${xv}" y="${yc}" text-anchor="middle" style="paint-order:stroke;stroke:var(--surface);stroke-width:4px">${c}</text>`; }
        }
      });
    });
    return s + `</svg>`;
  }
  FIGURES["tabsigne-produit"] = () => tabsigne(["−∞", "−2", "3", "+∞"], [{ nom: "x + 2", cases: ["-", "0", "+", "", "+"] }, { nom: "3 − x", cases: ["+", "", "+", "0", "-"] }, { nom: "produit", cases: ["-", "0", "+", "0", "-"] }]);
  FIGURES["tabsigne-quotient"] = () => tabsigne(["−∞", "−4", "3", "+∞"], [{ nom: "x + 4", cases: ["-", "0", "+", "", "+"] }, { nom: "x − 3", cases: ["-", "", "-", "0", "+"] }, { nom: "quotient", cases: ["+", "0", "-", "||", "+"] }]);

