    const nom = (n) => `C<tspan class="sub" dy="3">${n}</tspan>`;
    const lab = (x, y, n) => `${n}(${x} ; ${y})`.replace(/-/g, "−");
    const base = { xmin, xmax, ymin, ymax, h: 260, xetiq: xmax - xmin > 11 ? 2 : 1, yetiq: 2, aria: `Parabole de f, de sommet S(${al} ; ${be})`.replace(/-/g, "−") };
