      const py = `${p === 1 ? "" : p === -1 ? "-" : p + " * "}x * x` + (q ? ` ${q < 0 ? "-" : "+"} ${Math.abs(q) === 1 ? "" : Math.abs(q) + " * "}x` : "") + (r ? ` ${r < 0 ? "-" : "+"} ${Math.abs(r)}` : "");
