      const I = [(A[0] + B[0]) / 2, (A[1] + B[1]) / 2], r2 = ((B[0] - A[0]) ** 2 + (B[1] - A[1]) ** 2) / 4, r = Math.sqrt(r2), rT = Number.isInteger(r) ? `${r}` : `\\sqrt{${r2}}`;
