    const VF = T.filter((x) => x[2].length === 1).map((x) => [x[0].replace(/^Vrai ou faux : « /, "").replace(/ »\s*[.?]?\s*$/, "").replace(/^./, (l) => l.toUpperCase()), x[1] === "Vrai", x[3].replace(/^(Vrai|Faux)[ .:]+/, "")]);
    const [n5, r5] = pick([[36, 6], [81, 9], [100, 10], [144, 12], [400, 20]]), e5 = +(3.6 / r5).toFixed(4), m5 = pick([10.8, 11.6, 11.9, 12.2]);
