    VF.push([`Avec un échantillon de $${n5}$ régimes et $\\sigma = 1{,}8$ kg, la marge $\\dfrac{2\\sigma}{\\sqrt{n}}$ vaut $${fr(e5)}$ kg`, true, `$\\dfrac{2 \\times 1{,}8}{\\sqrt{${n5}}} = \\dfrac{3{,}6}{${r5}} = ${fr(e5)}$ kg.`]);
    const [v6, ok6, ex6] = pick([[15, false], [14.5, false], [7.5, false], [7, false], [13, true, "$12$ et $14$"], [9, true, "$8$ et $10$"], [13.5, true, "$12$, $14$, $14$ et $14$"], [8.5, true, "$8$, $8$, $8$ et $10$"]]);
